WITH flattened_attrs AS (SELECT id, created_at, ship_to, attributes, ship_to.country AS ship_country, COALESCE(attributes['device'], 'unknown') AS device_or_default, SIZE(items) AS num_items, COALESCE(attributes['gift'], 'none') AS gift_or_default FROM carts) SELECT *, ROW_NUMBER() OVER (ORDER BY num_items DESC, id) AS seq_no, LAG(num_items, 2) OVER (PARTITION BY ship_country ORDER BY created_at, id) AS prev_num_items, NTILE(3) OVER (ORDER BY num_items, id) AS num_items_bucket, LAST_VALUE(num_items, TRUE) OVER (PARTITION BY ship_country ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_num_items FROM flattened_attrs
